name: OpenCode
run-name: "OpenCode #${{ github.event.issue.number || inputs.issue_number }}"
on:
  issues:
    types:
      - opened
  workflow_dispatch:
    inputs:
      issue_number:
        required: true
        type: string
        description: Existing issue to run
permissions: {}
concurrency:
  group: opencode-issue-${{ github.repository }}-${{ github.event.issue.number || inputs.issue_number }}
  cancel-in-progress: false
jobs:
  prepare:
    runs-on: ubuntu-latest
    permissions:
      id-token: write
      contents: write
      issues: write
      actions: write
    outputs:
      approved: ${{ steps.prepare.outputs.approved }}
      issue_number: ${{ steps.prepare.outputs.issue_number }}
      request: ${{ steps.prepare.outputs.request }}
      issue_title: ${{ steps.prepare.outputs.issue_title }}
      labels_json: ${{ steps.prepare.outputs.labels_json }}
      sender: ${{ steps.prepare.outputs.sender }}
      target_ref: ${{ steps.prepare.outputs.target_ref }}
      target_sha: ${{ steps.prepare.outputs.target_sha }}
    steps:
      - name: Authenticate status callbacks
        continue-on-error: true
        shell: bash
        env:
          ISSUE_NUMBER: ${{ github.event.issue.number || github.event.needs.prepare.outputs.issue_number }}
          OMGITHUB_ORIGIN: ${{ vars.OMGITHUB_ORIGIN || 'https://omgithub.com' }}
        run: |
          /usr/bin/time -p node --input-type=module <<'NODE'
          import { appendFileSync } from 'node:fs';
          const env = process.env;
          const origin = env.OMGITHUB_ORIGIN.replace(/\/$/, '');
          const url = new URL(env.ACTIONS_ID_TOKEN_REQUEST_URL);
          url.searchParams.set('audience', origin);
          async function json(url, options) {
            const response = await fetch(url, { ...options, signal: AbortSignal.timeout(15000) });
            if (!response.ok) throw new Error(`Callback authentication HTTP ${response.status}`);
            return response.json();
          }
          for (let attempt = 0; attempt < 8; attempt++) {
            try {
              const identity = await json(url, { headers: { authorization: `Bearer ${env.ACTIONS_ID_TOKEN_REQUEST_TOKEN}` } });
              const { token } = await json(`${origin}/api/github/${env.GITHUB_REPOSITORY}/issues/${env.ISSUE_NUMBER}/callback-token`, {
                method: 'POST', headers: { authorization: `Bearer ${identity.value}`, 'content-type': 'application/json' },
                body: JSON.stringify({ run: env.GITHUB_RUN_ID, attempt: Number(env.GITHUB_RUN_ATTEMPT) })
              });
              console.log(`::add-mask::${token}`);
              appendFileSync(env.GITHUB_ENV, `OMGITHUB_CALLBACK_TOKEN=${token}\n`);
              break;
            } catch (error) {
              if (attempt === 7) throw error;
              await new Promise(resolve => setTimeout(resolve, Math.min(20000, 3000 * 2 ** attempt)));
            }
          }
          NODE
      - name: Register preparation
        continue-on-error: true
        env:
          GH_TOKEN: ${{ github.token }}
          ISSUE_NUMBER: ${{ github.event.issue.number || github.event.needs.prepare.outputs.issue_number }}
          OMGITHUB_ORIGIN: ${{ vars.OMGITHUB_ORIGIN || 'https://omgithub.com' }}
        run: |
          /usr/bin/time -p curl --fail-with-body --silent --show-error --retry 2 --retry-all-errors --max-time 15 \
            -H "Authorization: Bearer $OMGITHUB_CALLBACK_TOKEN" -H 'Content-Type: application/json' \
            --data "{\"run\":\"$GITHUB_RUN_ID\",\"attempt\":$GITHUB_RUN_ATTEMPT,\"sequence\":1,\"state\":\"starting\",\"phase\":\"initializing\"}" \
            "$OMGITHUB_ORIGIN/api/github/$GITHUB_REPOSITORY/issues/$ISSUE_NUMBER/run"
      - name: Checkout trusted preparation code

